// ---------------------------------------------------------------------------
// WorkSense Skill Intelligence Graph engine — the shared, deterministic core.
// Zero LLM calls. Imported by backend functions (Recruitment, Onboarding,
// Recommendation Hub) — never recomputed per page view; results are persisted
// into the subject's digital_twins.computed_fits[].
// ---------------------------------------------------------------------------

export type VerificationRigor = "low" | "medium" | "high";

export interface SkillClaim {
  name: string;
  proficiency: number;
  evidence_source: string;
  verification_rigor: VerificationRigor;
}

export type EdgeType = "PREREQUISITE_OF" | "ADJACENT_TO" | "TRANSFERABLE_TO";

export interface GraphEdge {
  target_skill: string;
  type: EdgeType;
  weight: number; // 0.0 - 1.0
}

export interface GraphSkill {
  skill: string;
  category: string;
  outgoing_edges: GraphEdge[];
}

export interface RequiredSkill {
  skill: string;
  target_proficiency: number;
}

export type Classification = "direct" | "adjacent" | "transferable" | "gap";

export interface FitItem {
  skill: string;
  classification: Classification;
  required_proficiency: number;
  candidate_proficiency: number | null;
  edge: { from_skill: string; type: EdgeType; weight: number } | null;
  contribution: number | null;
  reason: string;
}

export interface FitRecord {
  target_type: "requisition";
  target_id: string;
  target_title: string;
  scenario: "current" | "future";
  score: number;
  sections: {
    direct: { value: number; items: FitItem[] };
    adjacent: { value: number; items: FitItem[] };
    evidence: { value: number; artifact_count: number; threshold: number };
    seniority: { value: number; candidate_level: number; role_level: number };
  };
  classification: {
    direct: FitItem[];
    adjacent: FitItem[];
    transferable: FitItem[];
    gaps: FitItem[];
  };
  computed_at: string;
}

// Validated weights — do not change.
export const MATCH_WEIGHTS = {
  direct: 0.5,
  adjacent: 0.25,
  evidence: 0.15,
  seniority: 0.1,
} as const;

export const DEFAULT_EVIDENCE_THRESHOLD = 5;

const norm = (s: string) => s.trim().toLowerCase();

export function findEdge(
  skillGraph: GraphSkill[],
  from: string,
  to: string,
  type: EdgeType
): GraphEdge | null {
  const node = skillGraph.find((n) => norm(n.skill) === norm(from));
  const edge = node?.outgoing_edges.find(
    (e) => norm(e.target_skill) === norm(to) && e.type === type
  );
  return edge ?? null;
}

const round3 = (n: number) => Math.round(n * 1000) / 1000;

export function computeFit(params: {
  candidateSkills: SkillClaim[];
  candidateLevel: number;
  requiredSkills: RequiredSkill[];
  roleLevel: number;
  skillGraph: GraphSkill[];
  threshold?: number;
  target: { type: "requisition"; id: string; title: string };
  scenario: "current" | "future";
  computedAt?: string;
}): FitRecord {
  const threshold = params.threshold ?? DEFAULT_EVIDENCE_THRESHOLD;
  const graph = params.skillGraph;

  const directItems: FitItem[] = [];
  const adjacentItems: FitItem[] = [];
  const transferableItems: FitItem[] = [];
  const gapItems: FitItem[] = [];
  const directValues: number[] = [];
  const adjacentValues: number[] = [];

  let ownedCount = 0;
  for (const req of params.requiredSkills) {
    const own = params.candidateSkills.find((s) => norm(s.name) === norm(req.skill));
    const ownProficiency = own?.proficiency ?? 0;

    // S_direct: min(1, candidate/required) across ALL required skills — 0 for
    // skills not owned; partial proficiency still contributes its ratio.
    const ratio = own ? Math.min(1, ownProficiency / req.target_proficiency) : 0;
    directValues.push(ratio);

    if (own) {
      ownedCount++;
      if (ownProficiency >= req.target_proficiency) {
        directItems.push({
          skill: req.skill,
          classification: "direct",
          required_proficiency: req.target_proficiency,
          candidate_proficiency: ownProficiency,
          edge: null,
          contribution: ratio,
          reason: `Holds ${req.skill} at ${ownProficiency}/${req.target_proficiency} required.`,
        });
      } else {
        directItems.push({
          skill: req.skill,
          classification: "direct",
          required_proficiency: req.target_proficiency,
          candidate_proficiency: ownProficiency,
          edge: null,
          contribution: ratio,
          reason: `Holds ${req.skill} at ${ownProficiency}/${req.target_proficiency} — below the required bar.`,
        });
      }
      continue;
    }

    // Adjacent: no direct skill, but a real ADJACENT_TO edge exists (with the
    // candidate's proficiency weighting the edge). Never a direct equivalence.
    let bestAdj: { from: string; edge: GraphEdge; value: number } | null = null;
    for (const claim of params.candidateSkills) {
      const edge = findEdge(graph, claim.name, req.skill, "ADJACENT_TO");
      if (edge) {
        const value = (claim.proficiency / 5) * edge.weight;
        if (!bestAdj || value > bestAdj.value) bestAdj = { from: claim.name, edge, value };
      }
    }
    if (bestAdj) {
      adjacentValues.push(bestAdj.value);
      adjacentItems.push({
        skill: req.skill,
        classification: "adjacent",
        required_proficiency: req.target_proficiency,
        candidate_proficiency: ownProficiency || null,
        edge: { from_skill: bestAdj.from, type: "ADJACENT_TO", weight: bestAdj.edge.weight },
        contribution: bestAdj.value,
        reason: `No direct ${req.skill}; backed by ${bestAdj.from} → ${req.skill} (ADJACENT_TO, ${bestAdj.edge.weight.toFixed(2)}).`,
      });
      continue;
    }

    // Transferable: no direct/adjacent edge, but a TRANSFERABLE_TO edge or a
    // strong same-category relationship exists.
    let transfer: { from: string; edge: GraphEdge | null; via: string } | null = null;
    for (const claim of params.candidateSkills) {
      const edge = findEdge(graph, claim.name, req.skill, "TRANSFERABLE_TO");
      if (edge) {
        transfer = { from: claim.name, edge, via: "edge" };
        break;
      }
      if (!transfer) {
        const ownNode = graph.find((n) => norm(n.skill) === norm(claim.name));
        const reqNode = graph.find((n) => norm(n.skill) === norm(req.skill));
        if (ownNode && reqNode && ownNode.category && ownNode.category === reqNode.category) {
          transfer = { from: claim.name, edge: null, via: `same category (${ownNode.category})` };
        }
      }
    }
    if (transfer) {
      transferableItems.push({
        skill: req.skill,
        classification: "transferable",
        required_proficiency: req.target_proficiency,
        candidate_proficiency: ownProficiency || null,
        edge: transfer.edge
          ? { from_skill: transfer.from, type: "TRANSFERABLE_TO", weight: transfer.edge.weight }
          : null,
        contribution: null,
        reason: transfer.edge
          ? `No direct or adjacent path; ${transfer.from} → ${req.skill} is transferable.`
          : `No direct or adjacent path; ${transfer.from} shares the ${transfer.via}.`,
      });
      continue;
    }

    gapItems.push({
      skill: req.skill,
      classification: "gap",
      required_proficiency: req.target_proficiency,
      candidate_proficiency: ownProficiency || null,
      edge: null,
      contribution: null,
      reason: `No direct, adjacent, or transferable path found for ${req.skill}.`,
    });
  }

  const S_direct =
    directValues.length > 0
      ? directValues.reduce((a, b) => a + b, 0) / directValues.length
      : 0;

  const missing = params.requiredSkills.length - ownedCount; // skills not owned at all
  const S_adjacent =
    missing === 0
      ? 1 // nothing missing to be adjacent to
      : adjacentValues.length > 0
        ? adjacentValues.reduce((a, b) => a + b, 0) / missing
        : 0;

  const artifactCount = params.candidateSkills.filter(
    (s) => s.verification_rigor === "high" || s.verification_rigor === "medium"
  ).length;
  const S_evidence = Math.min(1, artifactCount / threshold);

  const S_seniority = Math.max(0, 1 - 0.2 * Math.abs(params.candidateLevel - params.roleLevel));

  const score =
    MATCH_WEIGHTS.direct * S_direct +
    MATCH_WEIGHTS.adjacent * S_adjacent +
    MATCH_WEIGHTS.evidence * S_evidence +
    MATCH_WEIGHTS.seniority * S_seniority;

  return {
    target_type: params.target.type,
    target_id: params.target.id,
    target_title: params.target.title,
    scenario: params.scenario,
    score: round3(score),
    sections: {
      direct: { value: round3(S_direct), items: directItems },
      adjacent: { value: round3(S_adjacent), items: adjacentItems },
      evidence: { value: round3(S_evidence), artifact_count: artifactCount, threshold },
      seniority: {
        value: round3(S_seniority),
        candidate_level: params.candidateLevel,
        role_level: params.roleLevel,
      },
    },
    classification: {
      direct: directItems,
      adjacent: adjacentItems,
      transferable: transferableItems,
      gaps: gapItems,
    },
    computed_at: params.computedAt ?? new Date().toISOString(),
  };
}

/** Cache key for computed_fits[] entries. */
export function fitKey(record: { target_type: string; target_id: string; scenario: string }) {
  return `${record.target_type}|${record.target_id}|${record.scenario}`;
}


// ---------------------------------------------------------------------------
// WorkSense Adaptive Onboarding engine — fully deterministic, zero LLM.
//  - Bloom-style waiver rule (proficiency >= target -> waive)
//  - Plan quality guard (non-waivable tasks)
//  - Kahn's topological scheduler + date assignment
//  - Blocker-aware date recomputation
// ---------------------------------------------------------------------------

export interface TaskInput {
  id: string;
  title: string;
  depends_on?: string[];
  skill?: string;
  target_proficiency?: number;
  non_waivable?: boolean;
  duration_days?: number;
}

export interface ScheduledTask extends TaskInput {
  depends_on: string[];
  duration_days: number;
  waived: boolean;
  status: "waived" | "pending" | "done" | "blocked";
  start_date: string | null;
  end_date: string | null;
  topological_level: number;
  blocked?: { note: string; reported_by: string; at: string } | null;
}

export interface Blocker {
  taskId: string;
  note: string;
  reported_by: string;
  at: string;
}

export class CycleError extends Error {
  constructor(message = "cyclic dependency detected in onboarding plan") {
    super(message);
    this.name = "CycleError";
  }
}

/** Non-negotiable tasks: never waived or deleted, regardless of skill match. */
export const NON_WAIVABLE_TASK_IDS = new Set(["security", "compliance_signoff", "payroll"]);

export function applyWaivers(
  tasks: TaskInput[],
  skills: { name: string; proficiency: number }[]
): { tasks: TaskInput[]; waived: string[]; required: string[] } {
  const skillMap = new Map(skills.map((s) => [s.name.toLowerCase(), s.proficiency]));
  const waived: string[] = [];
  const required: string[] = [];
  const out = tasks.map((t) => {
    if (t.non_waivable || NON_WAIVABLE_TASK_IDS.has(t.id)) {
      required.push(t.id);
      return t;
    }
    const prof = t.skill ? skillMap.get(t.skill.toLowerCase()) : undefined;
    if (prof !== undefined && prof >= (t.target_proficiency ?? 3)) {
      waived.push(t.id);
      return t;
    }
    required.push(t.id);
    return t;
  });
  return { tasks: out, waived, required };
}

const DAY_MS = 24 * 60 * 60 * 1000;

function addDays(d: Date, days: number): Date {
  return new Date(d.getTime() + days * DAY_MS);
}

/**
 * Kahn's topological scheduler, exactly as specified:
 * compute in-degree, queue zero-in-degree tasks, pop -> append -> decrement
 * dependents -> enqueue newly-zero. Any task not scheduled => cyclic error.
 * Start date = max(end of prerequisites) or the onboarding start date.
 */
export function schedulePlan(params: {
  tasks: TaskInput[];
  skills: { name: string; proficiency: number }[];
  startDate: string;
  blocked?: Blocker;
  doneTaskIds?: string[];
}): ScheduledTask[] {
  const { tasks: input, waived: waivedIds } = applyWaivers(params.tasks, params.skills);
  const ids = new Set(input.map((t) => t.id));
  for (const t of input) {
    for (const d of t.depends_on ?? []) {
      if (!ids.has(d)) throw new Error(`task ${t.id} depends on unknown task ${d}`);
    }
  }

  const indegree = new Map<string, number>();
  const adj = new Map<string, string[]>();
  for (const t of input) {
    indegree.set(t.id, (t.depends_on ?? []).length);
    for (const d of t.depends_on ?? []) {
      adj.set(d, [...(adj.get(d) ?? []), t.id]);
    }
  }

  const queue: string[] = [];
  for (const t of input) if ((indegree.get(t.id) ?? 0) === 0) queue.push(t.id);
  const order: string[] = [];
  while (queue.length > 0) {
    const id = queue.shift()!;
    order.push(id);
    for (const dep of adj.get(id) ?? []) {
      indegree.set(dep, (indegree.get(dep) ?? 0) - 1);
      if ((indegree.get(dep) ?? 0) === 0) queue.push(dep);
    }
  }
  if (order.length !== input.length) {
    throw new CycleError();
  }

  // Topological level (wave) per task for the DAG view.
  const level = new Map<string, number>();
  for (const id of order) {
    const t = input.find((x) => x.id === id)!;
    level.set(id, (t.depends_on ?? []).reduce((m, d) => Math.max(m, (level.get(d) ?? 0) + 1), 0));
  }

  const taskById = new Map(input.map((t) => [t.id, t]));
  const start = new Date(params.startDate);
  const endBy = new Map<string, Date | null>();
  const done = new Set(params.doneTaskIds ?? []);
  const scheduled: ScheduledTask[] = [];

  for (const id of order) {
    const t = taskById.get(id)!;
    const blocked = params.blocked?.taskId === id ? params.blocked : null;
    const blockedPrereq = (t.depends_on ?? []).find((d) => endBy.get(d) === null);

    let startDate: Date | null;
    let endDate: Date | null;
    if (blocked) {
      startDate = null;
      endDate = null;
    } else if (blockedPrereq) {
      // Waiting on a blocked prerequisite — downstream dates recompute to null.
      startDate = null;
      endDate = null;
    } else {
      const prereqEnds = (t.depends_on ?? [])
        .map((d) => endBy.get(d))
        .filter((d): d is Date => d instanceof Date);
      const base = prereqEnds.length > 0 ? new Date(Math.max(...prereqEnds.map((d) => d.getTime()))) : new Date(start);
      startDate = base;
      endDate = addDays(base, t.duration_days ?? 1);
    }
    endBy.set(id, endDate);

    const isDone = done.has(id);
    const status: ScheduledTask["status"] = isDone
      ? "done"
      : blocked
        ? "blocked"
        : waivedIds.includes(id)
          ? "waived"
          : "pending";

    scheduled.push({
      id: t.id,
      title: t.title,
      depends_on: [...(t.depends_on ?? [])],
      skill: t.skill,
      target_proficiency: t.target_proficiency,
      non_waivable: t.non_waivable || NON_WAIVABLE_TASK_IDS.has(t.id),
      duration_days: t.duration_days ?? 1,
      waived: waivedIds.includes(id),
      status,
      start_date: startDate ? startDate.toISOString() : null,
      end_date: endDate ? endDate.toISOString() : null,
      topological_level: level.get(id) ?? 0,
      blocked: blocked ? { note: blocked.note, reported_by: blocked.reported_by, at: blocked.at } : null,
    });
  }

  return scheduled;
}


import { createClient } from "https://esm.sh/@supabase/supabase-js@2.39.0";



const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, "Content-Type": "application/json" } });

const normId = (s: string) => s.trim().toLowerCase().replace(/[^a-z0-9]+/g, "_");

const CORE_TASKS: TaskInput[] = [
  { id: "it", title: "IT & Laptop Provisioning", depends_on: [], duration_days: 1 },
  { id: "security", title: "Security & Compliance Training", depends_on: [], non_waivable: true, duration_days: 1 },
  { id: "payroll", title: "Direct Deposit & Payroll Setup", depends_on: [], non_waivable: true, duration_days: 0.5 },
  { id: "access", title: "System Access & SSO", depends_on: ["it", "security"], duration_days: 0.5 },
  { id: "compliance_signoff", title: "Compliance Sign-off", depends_on: ["security"], non_waivable: true, duration_days: 0.5 },
  { id: "team_intro", title: "Team Introduction & Codebase Walkthrough", depends_on: ["access"], duration_days: 1 },
];

async function isTeamMember(supabase, rootTwinId: string, checkTwinId: string): Promise<boolean> {
  const { data } = await supabase.from("digital_twins").select("id, manager_id");
  const children = new Map<string, string[]>();
  for (const t of data ?? []) {
    if (t.manager_id) children.set(t.manager_id, [...(children.get(t.manager_id) ?? []), t.id]);
  }
  const seen = new Set<string>();
  const stack = [rootTwinId];
  while (stack.length > 0) {
    const cur = stack.pop()!;
    if (seen.has(cur)) continue;
    seen.add(cur);
    for (const c of children.get(cur) ?? []) stack.push(c);
  }
  return seen.has(checkTwinId);
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL")!,
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
  );

  const authHeader = req.headers.get("Authorization") ?? "";
  const { data: userData } = await supabase.auth.getUser(authHeader.replace("Bearer ", ""));
  const uid = userData?.user?.id;
  if (!uid) return json({ error: "UNAUTHENTICATED" }, 401);

  const { data: caller } = await supabase
    .from("digital_twins")
    .select("id, role, email, org_id")
    .eq("auth_user_id", uid)
    .maybeSingle();
  if (!caller) return json({ error: "UNAUTHENTICATED" }, 401);

  let body: { twin_id?: string; req_id?: string; start_date?: string } = {};
  try {
    body = await req.json();
  } catch {
    /* empty */
  }
  const twinId = (body.twin_id ?? "").trim();
  if (!twinId) return json({ error: "VALIDATION_ERROR", message: "twin_id is required." }, 400);

  const { data: twin, error: twinErr } = await supabase
    .from("digital_twins")
    .select("id, org_id, role, name, job_title, verified_skills, seniority_level, computed_fits, audit_events")
    .eq("id", twinId)
    .maybeSingle();
  if (twinErr || !twin) return json({ error: "NOT_FOUND" }, 404);

  // Visibility: HR/partner see anyone; manager sees team + self; employee self only.
  let allowed = false;
  if (["hr_executive", "hr_partner"].includes(caller.role)) allowed = twin.org_id === caller.org_id;
  else if (caller.role === "manager" || caller.role === "employee") {
    allowed = twin.id === caller.id || (caller.role === "manager" && (await isTeamMember(supabase, caller.id, twin.id)));
  }
  if (!allowed) return json({ error: "FORBIDDEN" }, 403);

  // Role skills: explicit req, else a requisition whose title matches the job title.
  let reqRow: { id: string; title: string; required_skills: { skill: string; target_proficiency: number }[]; future_skills: { skill: string; target_proficiency: number }[]; seniority_level: number } | null = null;
  if (body.req_id) {
    const { data } = await supabase.from("job_requisitions").select("id, title, required_skills, future_skills, seniority_level").eq("id", body.req_id).maybeSingle();
    reqRow = data ?? null;
  }
  if (!reqRow) {
    const { data: all } = await supabase.from("job_requisitions").select("id, title, required_skills, future_skills, seniority_level");
    const job = (twin.job_title ?? "").toLowerCase();
    reqRow = (all ?? []).find(
      (r) => r.title.toLowerCase().includes(job) || job.includes(r.title.toLowerCase())
    ) ?? null;
  }

  const { data: graphRows } = await supabase
    .from("skill_graph")
    .select("skill, category, outgoing_edges")
    .eq("org_id", twin.org_id);

  const now = new Date().toISOString();
  const startDate = body.start_date ?? now;

  // Requirement 1: fit vs the employee's own role — current AND future skills.
  const fits = (twin.computed_fits ?? []) as { target_id: string; scenario: string }[];
  const fitCurrent = computeFit({
    candidateSkills: twin.verified_skills ?? [],
    candidateLevel: twin.seniority_level ?? 3,
    requiredSkills: reqRow?.required_skills ?? [],
    roleLevel: reqRow?.seniority_level ?? 3,
    skillGraph: graphRows ?? [],
    target: { type: "requisition", id: reqRow?.id ?? "own-role", title: reqRow?.title ?? twin.job_title ?? "Role" },
    scenario: "current",
    computedAt: now,
  });
  const fitFuture = computeFit({
    candidateSkills: twin.verified_skills ?? [],
    candidateLevel: twin.seniority_level ?? 3,
    requiredSkills: reqRow?.future_skills ?? [],
    roleLevel: reqRow?.seniority_level ?? 3,
    skillGraph: graphRows ?? [],
    target: { type: "requisition", id: reqRow?.id ?? "own-role", title: reqRow?.title ?? twin.job_title ?? "Role" },
    scenario: "future",
    computedAt: now,
  });
  const nextFits = fits.filter((f) => !(f.target_id === fitCurrent.target_id && f.scenario === "current") && !(f.target_id === fitFuture.target_id && f.scenario === "future")).concat([fitCurrent, fitFuture] as unknown as { target_id: string; scenario: string }[]);

  // Build the task graph: core + role skills + future skills + survey.
  const tasks: TaskInput[] = [...CORE_TASKS];
  const required = (reqRow?.required_skills ?? []).slice(0, 3);
  const future = (reqRow?.future_skills ?? []).slice(0, 2);
  const firstSkillId = required.length > 0 ? `skill_${normId(required[0].skill)}` : "team_intro";
  for (const s of required) {
    tasks.push({
      id: `skill_${normId(s.skill)}`,
      title: `First contribution using ${s.skill}`,
      skill: s.skill,
      target_proficiency: s.target_proficiency,
      depends_on: ["team_intro"],
      duration_days: 1,
    });
  }
  for (const s of future) {
    tasks.push({
      id: `future_${normId(s.skill)}`,
      title: `Upskilling plan: ${s.skill}`,
      skill: s.skill,
      target_proficiency: s.target_proficiency,
      depends_on: [firstSkillId],
      duration_days: 1,
    });
  }
  tasks.push({ id: "survey", title: "Onboarding Feedback Survey", depends_on: [firstSkillId], duration_days: 0.5 });

  let scheduled;
  try {
    scheduled = schedulePlan({
      tasks,
      skills: (twin.verified_skills ?? []) as { name: string; proficiency: number }[],
      startDate,
    });
  } catch (err) {
    if (err instanceof CycleError) {
      return json({ error: "VALIDATION_ERROR", message: err.message }, 400);
    }
    throw err;
  }

  const { data: existing } = await supabase
    .from("onboarding_journeys")
    .select("id, status, plan, audit_events")
    .eq("twin_id", twinId)
    .maybeSingle();

  const plan = {
    start_date: startDate,
    approvals: (existing?.plan as { approvals?: unknown[] })?.approvals ?? [],
    fit_current: fitCurrent.score,
    fit_future: fitFuture.score,
    generated_at: now,
  };
  const audit = [
    ...((existing?.audit_events as unknown[]) ?? []),
    { actor: caller.email ?? uid, action: existing ? "plan_regenerated" : "plan_generated", note: `Onboarding plan for ${twin.name}: ${scheduled.length} tasks, ${scheduled.filter((t) => t.waived).length} waived.`, timestamp: now },
  ];

  let journeyId = existing?.id;
  if (existing) {
    await supabase
      .from("onboarding_journeys")
      .update({ tasks: scheduled, status: "pending", plan, audit_events: audit })
      .eq("id", existing.id);
  } else {
    const { data: inserted, error: insErr } = await supabase
      .from("onboarding_journeys")
      .insert({ org_id: twin.org_id, twin_id: twinId, tasks: scheduled, status: "pending", plan, audit_events: audit })
      .select("id")
      .single();
    if (insErr) return json({ error: "INTERNAL", message: insErr.message }, 500);
    journeyId = inserted.id;
  }

  // Persist fits + audit on the twin.
  await supabase
    .from("digital_twins")
    .update({
      computed_fits: nextFits,
      audit_events: [
        ...(twin.audit_events ?? []),
        { actor: caller.email ?? uid, action: "plan_fit_computed", note: `Role fit current ${fitCurrent.score.toFixed(2)} / future ${fitFuture.score.toFixed(2)}.`, timestamp: now },
      ],
    })
    .eq("id", twinId);

  return json({ ok: true, journey: { id: journeyId, status: "pending", plan, tasks: scheduled } });
});
